function executeSkill(context) {
  var caster = context.piece; var player = battle.players.find(function(p) { return p.playerId === caster.ownerPlayerId; });
  if (!player) return { success: false, message: '未找到玩家' };
  function isOrdinaryHoly(card) {
  return card && ['holy-smite', 'holy-heal', 'holy-charge'].indexOf(card.cardId) !== -1;
}
  var eligible = player.hand.filter(function(card) { return isOrdinaryHoly(card) && !card.holyProphecyEnhanced; });
  if (eligible.length === 0) return { success: false, message: '没有可强化的圣光手牌' };
  var options = eligible.map(function(card) { return { label: (card.name || card.cardId) + '（' + card.instanceId + '）', value: card.instanceId }; });
  var choice = selectOption({ title: '万千未来：选择立即强化的手牌', options: options, selectionMode: 'multi', presentation: 'hand', minSelections: 1, maxSelections: 3 });
  if (choice === undefined || choice === null || choice.needsOptionSelection) return choice;
  if (!Array.isArray(choice) || choice.length < 1 || choice.length > 3) return { success: false, message: '万千未来选择无效' };
  var unique = [];
  for (var i = 0; i < choice.length; i++) { if (unique.indexOf(choice[i]) !== -1) return { success: false, message: '不能重复选择同一张手牌' }; unique.push(choice[i]); }
  var selected = unique.map(function(id) { return eligible.find(function(card) { return card.instanceId === id; }); });
  if (selected.some(function(card) { return !card; })) return { success: false, message: '选择的手牌已无法强化' };
  selected.forEach(function(card) { card.holyProphecyEnhanced = true; delete card.holyProphecy; });
  return { success: true, message: caster.name + '从' + selected.length + '种圣光的可能中选定了未来' };
}
